package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Path;
import org.junit.jupiter.api.Test;

class SingleEntryArchiveFormatMutaGate1Test {

  @Test
  void gzipHostArchiveReturnsFileSystemGzipFile() throws Exception {
    Path gzip = Files.createTempFile("mutagate", ".gz");
    Path temp = Files.createTempFile("mutagate", ".tmp");
    try {
      GzipFileSystem fs =
          new GzipFileSystem(
              new GzipFileSystemProvider(),
              URI.create("gzip:" + gzip.toUri()),
              gzip,
              "entry",
              temp);

      Path result = SingleEntryArchiveFormat.GZIP.hostArchive(fs);

      assertNotNull(result);
      assertEquals(fs.gzipFile(), result);
    } finally {
      Files.deleteIfExists(gzip);
      Files.deleteIfExists(temp);
    }
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertInstanceOf;
import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.io.IOException;
import java.nio.file.FileStore;
import java.nio.file.FileSystem;
import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.nio.file.WatchService;
import java.nio.file.attribute.BasicFileAttributeView;
import java.nio.file.attribute.UserPrincipalLookupService;
import java.nio.file.spi.FileSystemProvider;
import java.util.Collections;
import java.util.Set;
import org.junit.jupiter.api.Test;

class SingleEntryArchiveFormatMutaGate2Test {

  private static final class StubFileSystem extends FileSystem {
    @Override
    public FileSystemProvider provider() {
      return null;
    }

    @Override
    public void close() throws IOException {}

    @Override
    public boolean isOpen() {
      return true;
    }

    @Override
    public boolean isReadOnly() {
      return true;
    }

    @Override
    public String getSeparator() {
      return "/";
    }

    @Override
    public Iterable<Path> getRootDirectories() {
      return Collections.emptyList();
    }

    @Override
    public Iterable<FileStore> getFileStores() {
      return Collections.emptyList();
    }

    @Override
    public Set<String> supportedFileAttributeViews() {
      return Collections.singleton("basic");
    }

    @Override
    public Path getPath(String first, String... more) {
      throw new UnsupportedOperationException();
    }

    @Override
    public PathMatcher getPathMatcher(String syntaxAndPattern) {
      throw new UnsupportedOperationException();
    }

    @Override
    public UserPrincipalLookupService getUserPrincipalLookupService() {
      throw new UnsupportedOperationException();
    }

    @Override
    public WatchService newWatchService() throws IOException {
      throw new UnsupportedOperationException();
    }
  }

  @Test
  void gzipNewBasicAttributeViewReturnsGzipView() {
    SingleEntryArchivePath path =
        new SingleEntryArchivePath(
            new StubFileSystem(), SingleEntryArchiveFormat.GZIP, true, "entry");

    BasicFileAttributeView view = SingleEntryArchiveFormat.GZIP.newBasicAttributeView(path);

    assertNotNull(view);
    assertInstanceOf(GzipBasicFileAttributeView.class, view);
  }
}

